export const virtualTourViewerHtmlString = "<!doctype html>\r\n<html>\r\n    <head>\r\n        <meta charset=\"utf-8\" />\r\n        <meta\r\n            name=\"viewport\"\r\n            content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, orientation=landscape\"\r\n        />\r\n        <style>\r\n            body {\r\n                margin: 0;\r\n                overflow: hidden;\r\n                background: #000000;\r\n            }\r\n            #canvas {\r\n                width: 100%;\r\n                height: 100%;\r\n                display: block;\r\n            }\r\n            #loading {\r\n                position: absolute;\r\n                top: 50%;\r\n                left: 50%;\r\n                transform: translate(-50%, -50%);\r\n                color: #00e5ff;\r\n                font-weight: bold;\r\n                font-family: system-ui;\r\n                letter-spacing: 2px;\r\n            }\r\n            #joystick-zone {\r\n                position: absolute;\r\n                bottom: 20px;\r\n                left: 20px;\r\n                width: 120px;\r\n                height: 120px;\r\n                background: rgba(255, 255, 255, 0.1);\r\n                border-radius: 50%;\r\n                border: 2px solid rgba(0, 229, 255, 0.3);\r\n                pointer-events: none;\r\n            }\r\n            #instructions {\r\n                position: absolute;\r\n                bottom: 20px;\r\n                right: 20px;\r\n                text-align: right;\r\n                color: rgba(255, 255, 255, 0.7);\r\n                font-family: system-ui;\r\n                font-size: 12px;\r\n                pointer-events: none;\r\n            }\r\n            #ghost-btn {\r\n                position: absolute;\r\n                top: 80px;\r\n                right: 20px;\r\n                background: rgba(0, 229, 255, 0.2);\r\n                color: #00e5ff;\r\n                border: 1px solid #00e5ff;\r\n                padding: 8px 12px;\r\n                border-radius: 8px;\r\n                font-family: system-ui;\r\n                font-weight: bold;\r\n                z-index: 100;\r\n                display: none;\r\n            }\r\n            #camera-zone {\r\n                position: absolute;\r\n                top: 0;\r\n                right: 0;\r\n                width: 50%;\r\n                height: 100%;\r\n                z-index: 10;\r\n            }\r\n            #crosshair {\r\n                position: absolute;\r\n                top: 50%;\r\n                left: 50%;\r\n                width: 6px;\r\n                height: 6px;\r\n                background: rgba(255, 255, 255, 0.8);\r\n                border-radius: 50%;\r\n                transform: translate(-50%, -50%);\r\n                z-index: 50;\r\n                pointer-events: none;\r\n            }\r\n            #info-panel {\r\n                position: absolute;\r\n                background: rgba(0, 0, 0, 0.85);\r\n                border: 2px solid #00e5ff;\r\n                color: white;\r\n                padding: 15px;\r\n                border-radius: 12px;\r\n                width: 220px;\r\n                text-align: center;\r\n                font-family: system-ui;\r\n                z-index: 200;\r\n                display: none;\r\n                pointer-events: auto;\r\n                transform: translate(-50%, -100%);\r\n                margin-top: -15px; /* Spacing above head */\r\n                box-shadow: 0 10px 30px rgba(0, 229, 255, 0.2);\r\n            }\r\n            #info-panel::after {\r\n                content: '';\r\n                position: absolute;\r\n                bottom: -10px;\r\n                left: 50%;\r\n                transform: translateX(-50%);\r\n                border-width: 10px 10px 0;\r\n                border-style: solid;\r\n                border-color: #00e5ff transparent transparent transparent;\r\n                display: block;\r\n                width: 0;\r\n            }\r\n            #info-panel h2 {\r\n                margin-top: 0;\r\n                color: #00e5ff;\r\n            }\r\n            #info-close {\r\n                margin-top: 15px;\r\n                padding: 10px 20px;\r\n                background: #00e5ff;\r\n                color: black;\r\n                font-weight: bold;\r\n                border: none;\r\n                border-radius: 6px;\r\n                width: 100%;\r\n            }\r\n            .floating-label {\r\n                position: absolute;\r\n                background: rgba(0, 229, 255, 0.9);\r\n                color: #000;\r\n                font-weight: bold;\r\n                padding: 6px 14px;\r\n                border-radius: 14px;\r\n                font-family: system-ui, sans-serif;\r\n                font-size: 14px;\r\n                pointer-events: none;\r\n                transform: translate(-50%, -100%);\r\n                opacity: 0;\r\n                white-space: nowrap;\r\n                box-shadow: 0 4px 6px rgba(0,0,0,0.3);\r\n                transition: opacity 0.2s;\r\n                text-align: center;\r\n                z-index: 150;\r\n            }\r\n            .floating-label::after {\r\n                content: '';\r\n                position: absolute;\r\n                bottom: -6px;\r\n                left: 50%;\r\n                transform: translateX(-50%);\r\n                border-width: 6px 6px 0;\r\n                border-style: solid;\r\n                border-color: rgba(0, 229, 255, 0.9) transparent transparent transparent;\r\n                display: block;\r\n                width: 0;\r\n            }\r\n            .floating-label.restricted {\r\n                background: rgba(220, 53, 69, 0.9);\r\n                color: #fff;\r\n            }\r\n            .floating-label.restricted::after {\r\n                border-color: rgba(220, 53, 69, 0.9) transparent transparent transparent;\r\n            }\r\n            .floating-label.portal-label {\r\n                background: rgba(7, 42, 48, 0.92);\r\n                color: #00e5ff;\r\n                border: 1.5px solid #00e5ff;\r\n                box-shadow: 0 0 14px rgba(0, 229, 255, 0.45);\r\n                letter-spacing: 0.5px;\r\n            }\r\n            .floating-label.portal-label::after {\r\n                border-color: #00e5ff transparent transparent transparent;\r\n            }\r\n            /* ── Spawn Fade-In Overlay ─────────────────────────────── */\r\n            #spawn-fade {\r\n                position: absolute;\r\n                top: 0; left: 0; right: 0; bottom: 0;\r\n                background: #000;\r\n                opacity: 1;\r\n                pointer-events: none;\r\n                z-index: 300;\r\n                transition: opacity 0.7s ease-out;\r\n            }\r\n            #spawn-fade.faded {\r\n                opacity: 0;\r\n            }\r\n\r\n            /* ── Gyroscope mode indicator pill ─────────────────────── */\r\n\r\n            #gyro-indicator {\r\n                position: absolute;\r\n                top: 16px;\r\n                left: 50%;\r\n                transform: translateX(-50%);\r\n                background: rgba(46, 204, 113, 0.15);\r\n                border: 1px solid rgba(46, 204, 113, 0.6);\r\n                color: #2ecc71;\r\n                font-family: system-ui;\r\n                font-size: 11px;\r\n                font-weight: bold;\r\n                letter-spacing: 2px;\r\n                padding: 5px 14px;\r\n                border-radius: 20px;\r\n                z-index: 200;\r\n                display: none;\r\n                pointer-events: none;\r\n                white-space: nowrap;\r\n            }\r\n\r\n            /* ── Gyroscope permission banner (iOS 13+ needs user gesture) ── */\r\n            #gyro-permission-banner {\r\n                position: absolute;\r\n                top: 50%;\r\n                left: 50%;\r\n                transform: translate(-50%, -50%);\r\n                background: rgba(0, 0, 0, 0.92);\r\n                border: 2px solid #2ecc71;\r\n                color: white;\r\n                padding: 24px 20px;\r\n                border-radius: 14px;\r\n                width: 280px;\r\n                text-align: center;\r\n                font-family: system-ui;\r\n                z-index: 500;\r\n                display: none;\r\n            }\r\n            #gyro-permission-banner h3 {\r\n                margin: 0 0 10px;\r\n                color: #2ecc71;\r\n                font-size: 15px;\r\n                letter-spacing: 1px;\r\n            }\r\n            #gyro-permission-banner p {\r\n                margin: 0 0 16px;\r\n                color: rgba(255, 255, 255, 0.75);\r\n                font-size: 13px;\r\n                line-height: 1.5;\r\n            }\r\n            #gyro-allow-btn {\r\n                width: 100%;\r\n                padding: 12px;\r\n                background: #2ecc71;\r\n                color: black;\r\n                font-weight: bold;\r\n                border: none;\r\n                border-radius: 8px;\r\n                font-size: 14px;\r\n                cursor: pointer;\r\n            }\r\n        </style>\r\n        <!-- Include nipplejs for Joystick -->\r\n        <script src=\"https://cdnjs.cloudflare.com/ajax/libs/nipplejs/0.10.1/nipplejs.min.js\"></script>\r\n    </head>\r\n    <body>\r\n        <div id=\"loading\">INITIALIZING...</div>\r\n        <div id=\"instructions\">\r\n            Drag right side to look<br />Use joystick to move\r\n        </div>\r\n        <div id=\"joystick-zone\"></div>\r\n        <div id=\"camera-zone\"></div>\r\n        <button id=\"ghost-btn\" onclick=\"toggleGhostMode()\">PHYSICS: ON</button>\r\n        <div id=\"crosshair\"></div>\r\n\r\n        <!-- Gyroscope mode indicator -->\r\n        <div id=\"gyro-indicator\">⬡ GYROSCOPE ACTIVE</div>\r\n\r\n        <!-- Gyroscope permission banner (iOS 13+ DeviceOrientationEvent.requestPermission) -->\r\n        <div id=\"gyro-permission-banner\">\r\n            <h3>GYROSCOPE ACCESS</h3>\r\n            <p>\r\n                This mode uses your phone's built-in gyroscope to look around.\r\n                Please allow sensor access.\r\n            </p>\r\n            <button id=\"gyro-allow-btn\" onclick=\"requestGyroPermission()\">\r\n                ALLOW GYROSCOPE\r\n            </button>\r\n        </div>\r\n\r\n        <!-- Info panel is kept for backwards compatibility or clicks, but we'll use floating-labels for hover -->\r\n        <div id=\"info-panel\">\r\n            <h2 id=\"info-title\">Title</h2>\r\n            <p id=\"info-desc\">Description</p>\r\n            <button id=\"info-close\" onclick=\"closeInfoPanel()\">CLOSE</button>\r\n        </div>\r\n        \r\n        <div id=\"floating-labels\"></div>\r\n\r\n        <!-- Spawn fade-in overlay: covers scene during spawn, fades out once positioned -->\r\n        <div id=\"spawn-fade\"></div>\r\n\r\n        <canvas id=\"canvas\"></canvas>\r\n\r\n        <script type=\"importmap\">\r\n            {\r\n                \"imports\": {\r\n                    \"three\": \"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js\",\r\n                    \"three/addons/\": \"https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/\"\r\n                }\r\n            }\r\n        </script>\r\n        <script type=\"module\">\r\n            import * as THREE from \"three\";\r\n            import { GLTFLoader } from \"three/addons/loaders/GLTFLoader.js\";\r\n            import { DRACOLoader } from \"three/addons/loaders/DRACOLoader.js\";\r\n            import { OrbitControls } from \"three/addons/controls/OrbitControls.js\";\r\n\r\n            let scene, camera, renderer, controls, model, animFrameId;\r\n            let moveForward = 0;\r\n            let moveRight = 0;\r\n            let joystickManager;\r\n            let ghostMode = false;\r\n            let chunkCollector = {\r\n                totalChunks: 0,\r\n                chunks: [],\r\n                receivedCount: 0,\r\n                fallbackUrl: null,\r\n            };\r\n            let MOVE_SPEED = 0.18;\r\n            const COLLISION_DISTANCE = 0.38;\r\n            const floorRaycaster = new THREE.Raycaster();\r\n            floorRaycaster.far = 4.0;\r\n            const wallRaycaster = new THREE.Raycaster();\r\n            wallRaycaster.far = 1.0;\r\n            const downVector = new THREE.Vector3(0, -1, 0);\r\n            let worldBounds;\r\n\r\n            let hotspots = [];\r\n            let portalBadges = [];\r\n            let lastCamBroadcastTime = 0;\r\n            const tapRaycaster = new THREE.Raycaster();\r\n            const mouse = new THREE.Vector2();\r\n\r\n            // Teleportation state\r\n            let teleportTarget = null;\r\n            let teleportProgress = 0;\r\n            let teleportStartPos = new THREE.Vector3();\r\n            const TELEPORT_SPEED = 0.06;\r\n            let teleportMarker = null;\r\n\r\n            // ── Gyroscope state (Native Bridge — expo-sensors → postMessage) ──\r\n            // Android WebView does NOT fire deviceorientation events.\r\n            // Instead, React Native reads DeviceMotion natively and posts\r\n            // gyro_data messages to us at 60fps. We apply the standard\r\n            // Three.js DeviceOrientationControls math to those values.\r\n            let controlMode = \"joystick\"; // 'joystick' | 'gyroscope'\r\n            let gyroEnabled = false;\r\n\r\n            // Three.js DeviceOrientationControls constants\r\n            // q1: -90° around X — flips \"looking at floor\" → \"looking forward\"\r\n            const _zee = new THREE.Vector3(0, 0, 1);\r\n            const _eu = new THREE.Euler();\r\n            const _q0 = new THREE.Quaternion();\r\n            const _q1 = new THREE.Quaternion(\r\n                -Math.sqrt(0.5),\r\n                0,\r\n                0,\r\n                Math.sqrt(0.5),\r\n            );\r\n\r\n            const _latestDeviceQuat = new THREE.Quaternion();\r\n            const _targetCamQuat = new THREE.Quaternion();\r\n            let _yawOffsetQuat = null;\r\n            let _gyroDataReceived = false; // guard — don't apply until first packet\r\n\r\n            // Called every time a gyro_data message arrives from React Native\r\n            // orientAngleDeg is sent by RN (reliable) — 0=portrait, 90=landscape-right, 270=landscape-left\r\n            function onGyroData(alphaDeg, betaDeg, gammaDeg, orientAngleDeg) {\r\n                if (!gyroEnabled) return;\r\n\r\n                const alpha = THREE.MathUtils.degToRad(alphaDeg);\r\n                const beta = THREE.MathUtils.degToRad(betaDeg);\r\n                const gamma = THREE.MathUtils.degToRad(gammaDeg);\r\n                // Use orient from React Native — window.screen.orientation.angle is always 0 in Android WebViews\r\n                const orient = THREE.MathUtils.degToRad(orientAngleDeg || 90);\r\n\r\n                // Standard Three.js DeviceOrientationControls algorithm\r\n                // Ref: https://github.com/mrdoob/three.js/blob/dev/examples/jsm/controls/DeviceOrientationControls.js\r\n                _eu.set(beta, alpha, -gamma, \"YXZ\");\r\n                _latestDeviceQuat.setFromEuler(_eu);\r\n                _latestDeviceQuat.multiply(_q1); // correct \"looking at floor\"\r\n                _latestDeviceQuat.multiply(_q0.setFromAxisAngle(_zee, -orient)); // correct for landscape\r\n\r\n                // Calibrate YAW only on first reading so the camera starts looking where the joystick left off\r\n                // (We don't calibrate pitch/roll so the horizon stays level regardless of start orientation)\r\n                if (!_yawOffsetQuat && camera) {\r\n                    const vCam = new THREE.Vector3(0, 0, -1).applyQuaternion(\r\n                        camera.quaternion,\r\n                    );\r\n                    const vDev = new THREE.Vector3(0, 0, -1).applyQuaternion(\r\n                        _latestDeviceQuat,\r\n                    );\r\n                    vCam.y = 0;\r\n                    if (vCam.lengthSq() > 0.001) vCam.normalize();\r\n                    else vCam.set(0, 0, -1);\r\n                    vDev.y = 0;\r\n                    if (vDev.lengthSq() > 0.001) vDev.normalize();\r\n                    else vDev.set(0, 0, -1);\r\n\r\n                    const angle =\r\n                        Math.atan2(vCam.x, vCam.z) - Math.atan2(vDev.x, vDev.z);\r\n                    _yawOffsetQuat = new THREE.Quaternion().setFromAxisAngle(\r\n                        new THREE.Vector3(0, 1, 0),\r\n                        angle,\r\n                    );\r\n                }\r\n\r\n                _gyroDataReceived = true;\r\n            }\r\n\r\n            function startGyroscope() {\r\n                gyroEnabled = true;\r\n                document.getElementById(\"gyro-indicator\").style.display =\r\n                    \"block\";\r\n                document.getElementById(\"camera-zone\").style.pointerEvents =\r\n                    \"none\";\r\n                document.getElementById(\"instructions\").textContent =\r\n                    \"Tilt & rotate phone to look \\u00b7 Joystick to move\";\r\n                if (controls) controls.enabled = false;\r\n                // Reset calibration so it grabs a fresh heading if toggled off and on\r\n                _yawOffsetQuat = null;\r\n                _gyroDataReceived = false;\r\n            }\r\n\r\n            function applyGyroToCamera() {\r\n                if (\r\n                    !gyroEnabled ||\r\n                    !camera ||\r\n                    !_yawOffsetQuat ||\r\n                    !_gyroDataReceived\r\n                )\r\n                    return;\r\n\r\n                // Apply the yaw offset to the absolute device orientation\r\n                _targetCamQuat.multiplyQuaternions(\r\n                    _yawOffsetQuat,\r\n                    _latestDeviceQuat,\r\n                );\r\n\r\n                // Smooth interpolation\r\n                camera.quaternion.slerp(_targetCamQuat, 0.25);\r\n\r\n                // Sync OrbitControls target so joystick movement direction stays correct\r\n                if (model) {\r\n                    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(\r\n                        camera.quaternion,\r\n                    );\r\n                    controls.target\r\n                        .copy(camera.position)\r\n                        .addScaledVector(dir, 0.5);\r\n                }\r\n            }\r\n\r\n            // ── Panel helpers ──────────────────────────────────────────────\r\n            window.closeInfoPanel = () => {\r\n                document.getElementById(\"info-panel\").style.display = \"none\";\r\n            };\r\n\r\n            window.toggleGhostMode = () => {\r\n                ghostMode = !ghostMode;\r\n                document.getElementById(\"ghost-btn\").textContent = ghostMode\r\n                    ? \"PHYSICS: OFF (GHOST)\"\r\n                    : \"PHYSICS: ON\";\r\n                document.getElementById(\"ghost-btn\").style.background =\r\n                    ghostMode\r\n                        ? \"rgba(255, 0, 0, 0.2)\"\r\n                        : \"rgba(0, 229, 255, 0.2)\";\r\n                document.getElementById(\"ghost-btn\").style.color = ghostMode\r\n                    ? \"#FF4444\"\r\n                    : \"#00E5FF\";\r\n                document.getElementById(\"ghost-btn\").style.borderColor =\r\n                    ghostMode ? \"#FF4444\" : \"#00E5FF\";\r\n            };\r\n\r\n            // Allow tapping anywhere on the canvas / camera-zone to interact with hotspots/doors\r\n            let pointerDownPos = new THREE.Vector2();\r\n            document.addEventListener(\"pointerdown\", (e) => {\r\n                pointerDownPos.set(e.clientX, e.clientY);\r\n            });\r\n            let activeHotspot = null;\r\n\r\n            document.addEventListener(\"pointerup\", (e) => {\r\n                // If dragged more than 10 pixels, it's a drag (looking around), not a tap.\r\n                const dist = Math.hypot(e.clientX - pointerDownPos.x, e.clientY - pointerDownPos.y);\r\n                if (dist > 10) return;\r\n\r\n                if (e.target.id === \"canvas\" || e.target.id === \"camera-zone\") {\r\n                    mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\r\n                    mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\r\n\r\n                    tapRaycaster.setFromCamera(mouse, camera);\r\n                    const intersects = tapRaycaster.intersectObjects(\r\n                        hotspots,\r\n                        true,\r\n                    );\r\n\r\n                    if (intersects.length > 0) {\r\n                        let hit = intersects[0].object;\r\n                        if (hit.userData.isPortal) {\r\n                            window.ReactNativeWebView?.postMessage(\r\n                                JSON.stringify({\r\n                                    type: \"portal_clicked\",\r\n                                    sceneId: hit.userData.sceneId,\r\n                                    sceneTitle: hit.userData.sceneTitle,\r\n                                })\r\n                            );\r\n                            return;\r\n                        }\r\n                        if (hit.userData.title) {\r\n                            activeHotspot = hit; \r\n                            document.getElementById(\"info-title\").textContent = hit.userData.title;\r\n                            document.getElementById(\"info-desc\").textContent = hit.userData.desc;\r\n                            document.getElementById(\"info-panel\").style.display = \"block\";\r\n                        }\r\n                    } else if (model) {\r\n                        // Handle Teleportation on Model Floor\r\n                        const modelIntersects = tapRaycaster.intersectObject(model, true);\r\n                        if (modelIntersects.length > 0) {\r\n                            const hit = modelIntersects[0];\r\n                            // Check if the surface is mostly flat/horizontal (it's a floor)\r\n                            const normal = hit.face.normal.clone();\r\n                            if (hit.object.matrixWorld) {\r\n                                normal.transformDirection(hit.object.matrixWorld);\r\n                            }\r\n                            // y > 0.7 means it's pointing up (at least ~45 degrees)\r\n                            if (normal.y > 0.7) {\r\n                                // Start teleport\r\n                                teleportStartPos.copy(camera.position);\r\n                                // The new target is exactly the clicked point, plus eye height\r\n                                teleportTarget = new THREE.Vector3(hit.point.x, hit.point.y + 1.6, hit.point.z);\r\n                                teleportProgress = 0;\r\n                                \r\n                                // Show a marker briefly\r\n                                if (!teleportMarker) {\r\n                                    const markerGeom = new THREE.RingGeometry(0.2, 0.3, 32);\r\n                                    const markerMat = new THREE.MeshBasicMaterial({ color: 0x00E5FF, side: THREE.DoubleSide, transparent: true, opacity: 0.8 });\r\n                                    teleportMarker = new THREE.Mesh(markerGeom, markerMat);\r\n                                    teleportMarker.rotation.x = -Math.PI / 2;\r\n                                    scene.add(teleportMarker);\r\n                                }\r\n                                teleportMarker.position.copy(hit.point);\r\n                                teleportMarker.position.y += 0.05; // Slightly above ground\r\n                                teleportMarker.material.opacity = 0.8;\r\n                                teleportMarker.visible = true;\r\n                            }\r\n                        }\r\n                    }\r\n                }\r\n            });\r\n\r\n            // ── Scene Initialization ───────────────────────────────────────\r\n            function ensureScene(mode) {\r\n                if (scene) return;\r\n                controlMode = mode || controlMode || \"joystick\";\r\n\r\n                scene = new THREE.Scene();\r\n                scene.background = new THREE.Color(0x87ceeb); // Sky color\r\n\r\n                camera = new THREE.PerspectiveCamera(\r\n                    75,\r\n                    window.innerWidth / window.innerHeight,\r\n                    0.1,\r\n                    1000,\r\n                );\r\n\r\n                renderer = new THREE.WebGLRenderer({\r\n                    canvas: document.getElementById(\"canvas\"),\r\n                    antialias: true,\r\n                    powerPreference: \"high-performance\",\r\n                    precision: \"mediump\",\r\n                    depth: true,\r\n                    stencil: false,\r\n                });\r\n                renderer.setSize(window.innerWidth, window.innerHeight);\r\n                renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));\r\n\r\n                renderer.domElement.addEventListener(\"webglcontextlost\", (event) => {\r\n                    event.preventDefault();\r\n                    console.warn(\"WebGL Context Lost! Suspending animation loop.\");\r\n                    if (animFrameId) cancelAnimationFrame(animFrameId);\r\n                }, false);\r\n\r\n                renderer.domElement.addEventListener(\"webglcontextrestored\", () => {\r\n                    console.log(\"WebGL Context Restored! Resuming animation loop.\");\r\n                    animate();\r\n                }, false);\r\n\r\n                const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);\r\n                scene.add(ambientLight);\r\n\r\n                const directionalLight = new THREE.DirectionalLight(\r\n                    0xffffff,\r\n                    0.5,\r\n                );\r\n                directionalLight.position.set(5, 10, 7.5);\r\n                scene.add(directionalLight);\r\n\r\n                // First-person look controls bound ONLY to the right half of the screen\r\n                controls = new OrbitControls(\r\n                    camera,\r\n                    document.getElementById(\"camera-zone\"),\r\n                );\r\n                controls.enableDamping = true;\r\n                controls.dampingFactor = 0.25; // Snappy, instant finger response without floaty drag\r\n                controls.rotateSpeed = 0.85;  // Responsive head turning\r\n                controls.enableZoom = false;\r\n                controls.enablePan = false;\r\n\r\n                initJoystick();\r\n                animate();\r\n\r\n                if (controlMode === \"gyroscope\") {\r\n                    startGyroscope();\r\n                }\r\n\r\n                window.addEventListener(\"resize\", onWindowResize);\r\n            }\r\n\r\n            function init(modelUrl, mode) {\r\n                ensureScene(mode);\r\n                if (modelUrl) {\r\n                    loadModel(modelUrl);\r\n                }\r\n            }\r\n\r\n            // ── Joystick ───────────────────────────────────────────────────\r\n            function initJoystick() {\r\n                const zone = document.getElementById(\"joystick-zone\");\r\n                zone.style.pointerEvents = \"auto\";\r\n\r\n                joystickManager = nipplejs.create({\r\n                    zone: zone,\r\n                    mode: \"static\",\r\n                    position: { left: \"50%\", top: \"50%\" },\r\n                    color: \"#00E5FF\",\r\n                    size: 100,\r\n                });\r\n\r\n                joystickManager.on(\"move\", (evt, data) => {\r\n                    const angle = data.angle.radian;\r\n                    const force = Math.min(data.force, 1);\r\n                    // Nipplejs angles: 0=right, PI/2=up\r\n                    moveForward = Math.sin(angle) * force * MOVE_SPEED;\r\n                    moveRight = Math.cos(angle) * force * MOVE_SPEED;\r\n                });\r\n\r\n                joystickManager.on(\"end\", () => {\r\n                    moveForward = 0;\r\n                    moveRight = 0;\r\n                });\r\n            }\r\n\r\n            // ── Model Loading ──────────────────────────────────────────────\r\n            function onInteriorModelLoaded(gltf) {\r\n                console.log(\"Model loaded successfully\");\r\n                        model = gltf.scene;\r\n                        scene.add(model);\r\n\r\n                        // Calculate bounding box to place camera\r\n                        const box = new THREE.Box3().setFromObject(model);\r\n                        const center = box.getCenter(new THREE.Vector3());\r\n                        const size = box.getSize(new THREE.Vector3());\r\n\r\n                        worldBounds = box.clone();\r\n                        worldBounds.min.y -= 10;\r\n                        worldBounds.max.y += 10;\r\n\r\n                        // ── Smart Ground Floor Spawn Point Detection ─────────────────\r\n                        let spawnX = center.x;\r\n                        let spawnY = box.min.y + 1.6;\r\n                        let spawnZ = center.z;\r\n                        let spawnFacingAngle = 0; // will be overwritten by smart-facing\r\n\r\n                        // 1. If building has hotspots, prefer the first hotspot (intentional admin placement)\r\n                        if (window.buildingHotspots && window.buildingHotspots.length > 0) {\r\n                            const firstSpot = window.buildingHotspots[0];\r\n                            spawnX = Number(firstSpot.x);\r\n                            spawnY = Number(firstSpot.y) + 1.6;\r\n                            spawnZ = Number(firstSpot.z);\r\n                        } else {\r\n                            // 2. Grid Raycast — cast 5×5 = 25 rays across the building footprint.\r\n                            //    Handles L-shapes, courtyards, and buildings where the center is open air.\r\n                            //    Each ray is spaced at 20% of the building's X/Z dimensions.\r\n                            const spawnRaycaster = new THREE.Raycaster();\r\n                            const downDir = new THREE.Vector3(0, -1, 0);\r\n                            const GRID = 5; // 5×5 grid\r\n                            const allFloorHits = [];\r\n\r\n                            for (let gx = 0; gx < GRID; gx++) {\r\n                                for (let gz = 0; gz < GRID; gz++) {\r\n                                    // Sample points evenly from 10%–90% of the footprint (avoid edges)\r\n                                    const px = box.min.x + size.x * (0.1 + (gx / (GRID - 1)) * 0.8);\r\n                                    const pz = box.min.z + size.z * (0.1 + (gz / (GRID - 1)) * 0.8);\r\n                                    const origin = new THREE.Vector3(px, box.max.y + 5, pz);\r\n                                    spawnRaycaster.set(origin, downDir);\r\n                                    const hits = spawnRaycaster.intersectObject(model, true);\r\n\r\n                                    // 3. Floor Cluster Filter — discard underground slabs and rooftops.\r\n                                    //    Only keep hits in the lowest 2m band above the true model floor.\r\n                                    const trueFloor = box.min.y + 0.05; // above any foundation slab\r\n                                    const floorBandTop = trueFloor + 2.0; // 2m band = ground floor only\r\n                                    hits.forEach(h => {\r\n                                        if (h.point.y >= trueFloor && h.point.y <= floorBandTop) {\r\n                                            allFloorHits.push(h.point);\r\n                                        }\r\n                                    });\r\n                                }\r\n                            }\r\n\r\n                            if (allFloorHits.length > 0) {\r\n                                // Pick the average position of all valid floor hits as the spawn center.\r\n                                // More hits = denser area = more reliable interior location (majority vote).\r\n                                const avgX = allFloorHits.reduce((s, p) => s + p.x, 0) / allFloorHits.length;\r\n                                const avgY = allFloorHits.reduce((s, p) => s + p.y, 0) / allFloorHits.length;\r\n                                const avgZ = allFloorHits.reduce((s, p) => s + p.z, 0) / allFloorHits.length;\r\n                                spawnX = avgX;\r\n                                spawnY = avgY + 1.6; // human eye height\r\n                                spawnZ = avgZ;\r\n                            } else {\r\n                                // Fallback: brute-force 4 cardinal offsets if grid found nothing\r\n                                const offsets = [\r\n                                    [0, 0],\r\n                                    [0,  size.z * 0.3],\r\n                                    [0, -size.z * 0.3],\r\n                                    [ size.x * 0.2, 0],\r\n                                    [-size.x * 0.2, 0],\r\n                                ];\r\n                                let found = false;\r\n                                for (const [dx, dz] of offsets) {\r\n                                    const origin = new THREE.Vector3(center.x + dx, box.max.y + 5, center.z + dz);\r\n                                    spawnRaycaster.set(origin, downDir);\r\n                                    const hits = spawnRaycaster.intersectObject(model, true);\r\n                                    const trueFloor = box.min.y + 0.05;\r\n                                    const valid = hits.filter(h => h.point.y >= trueFloor);\r\n                                    if (valid.length > 0) {\r\n                                        const lowest = valid.sort((a, b) => a.point.y - b.point.y)[0];\r\n                                        spawnX = lowest.point.x;\r\n                                        spawnY = lowest.point.y + 1.6;\r\n                                        spawnZ = lowest.point.z;\r\n                                        found = true;\r\n                                        break;\r\n                                    }\r\n                                }\r\n                                // Last resort: use bounding box floor\r\n                                if (!found) {\r\n                                    spawnX = center.x;\r\n                                    spawnY = box.min.y + 1.6;\r\n                                    spawnZ = center.z;\r\n                                }\r\n                            }\r\n                        }\r\n\r\n                        // 4. Smart Facing Direction — fire 8 short raycasts around spawn point.\r\n                        //    Pick the direction with the MOST free space so player faces into the room.\r\n                        {\r\n                            const facingRaycaster = new THREE.Raycaster();\r\n                            facingRaycaster.far = 4.0;\r\n                            const spawnEye = new THREE.Vector3(spawnX, spawnY, spawnZ);\r\n                            const DIRECTIONS_8 = [0, 45, 90, 135, 180, 225, 270, 315]; // degrees\r\n                            let bestAngle = 0;\r\n                            let bestDist  = -1;\r\n\r\n                            DIRECTIONS_8.forEach(deg => {\r\n                                const rad = THREE.MathUtils.degToRad(deg);\r\n                                const dir = new THREE.Vector3(Math.sin(rad), 0, Math.cos(rad));\r\n                                facingRaycaster.set(spawnEye, dir);\r\n                                const hits = facingRaycaster.intersectObject(model, true);\r\n                                const dist = hits.length > 0 ? hits[0].distance : facingRaycaster.far;\r\n                                if (dist > bestDist) {\r\n                                    bestDist  = dist;\r\n                                    bestAngle = rad;\r\n                                }\r\n                            });\r\n                            spawnFacingAngle = bestAngle;\r\n                        }\r\n\r\n                        // Store default safe spawn position for void recovery\r\n                        window.safeSpawnPos = new THREE.Vector3(spawnX, spawnY, spawnZ);\r\n\r\n                        // Position camera at spawn point\r\n                        camera.position.set(spawnX, spawnY, spawnZ);\r\n\r\n                        // Face the most-open direction instead of always -Z\r\n                        const facingTarget = new THREE.Vector3(\r\n                            spawnX + Math.sin(spawnFacingAngle),\r\n                            spawnY,\r\n                            spawnZ + Math.cos(spawnFacingAngle),\r\n                        );\r\n                        controls.target.copy(facingTarget);\r\n                        controls.update();\r\n\r\n                        // Trigger spawn fade-in: black overlay fades out smoothly after 1 rendered frame\r\n                        requestAnimationFrame(() => {\r\n                            requestAnimationFrame(() => {\r\n                                const fadeEl = document.getElementById('spawn-fade');\r\n                                if (fadeEl) {\r\n                                    fadeEl.classList.add('faded');\r\n                                    // Remove from DOM after transition so it doesn't block pointer events\r\n                                    fadeEl.addEventListener('transitionend', () => fadeEl.remove(), { once: true });\r\n                                }\r\n                            });\r\n                        });\r\n\r\n                        // Safety ground plane under model so the player never falls into the void\r\n                        const groundGeom = new THREE.PlaneGeometry(Math.max(2000, size.x * 10), Math.max(2000, size.z * 10));\r\n                        const groundMat = new THREE.MeshBasicMaterial({ color: 0x5a6a72, depthWrite: true });\r\n                        const groundPlane = new THREE.Mesh(groundGeom, groundMat);\r\n                        groundPlane.rotation.x = -Math.PI / 2;\r\n                        groundPlane.position.set(center.x, box.min.y, center.z);\r\n                        scene.add(groundPlane);\r\n\r\n                        // ── Create Interactive Hotspots (NPC) ──────────────────────\r\n                        const createHotspot = (x, y, z, title, desc, color, category) => {\r\n                            const npcGroup = new THREE.Group();\r\n                            npcGroup.position.set(x, y, z);\r\n\r\n                            const skinMat = new THREE.MeshBasicMaterial({ color: 0xffe0bd, depthTest: false });\r\n                            const clothesMat = new THREE.MeshBasicMaterial({ color: 0x8a1538, depthTest: false }); // WMSU Crimson\r\n                            const pantsMat = new THREE.MeshBasicMaterial({ color: 0x333333, depthTest: false });\r\n\r\n                            // Torso\r\n                            const torsoGeom = new THREE.BoxGeometry(0.4, 0.6, 0.2);\r\n                            const torso = new THREE.Mesh(torsoGeom, clothesMat);\r\n                            torso.position.y = 1.0;\r\n                            torso.renderOrder = 999;\r\n                            npcGroup.add(torso);\r\n\r\n                            // Head\r\n                            const headGroup = new THREE.Group();\r\n                            headGroup.position.y = 1.45;\r\n\r\n                            const headGeom = new THREE.SphereGeometry(0.18, 16, 16);\r\n                            const head = new THREE.Mesh(headGeom, skinMat);\r\n                            head.renderOrder = 999;\r\n                            headGroup.add(head);\r\n\r\n                            // Eyes\r\n                            const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false });\r\n                            const eyeGeom = new THREE.SphereGeometry(0.02, 8, 8);\r\n                            const leftEye = new THREE.Mesh(eyeGeom, eyeMat);\r\n                            leftEye.position.set(-0.06, 0.03, 0.16);\r\n                            leftEye.renderOrder = 999;\r\n                            const rightEye = new THREE.Mesh(eyeGeom, eyeMat);\r\n                            rightEye.position.set(0.06, 0.03, 0.16);\r\n                            rightEye.renderOrder = 999;\r\n                            headGroup.add(leftEye);\r\n                            headGroup.add(rightEye);\r\n\r\n                            // Smile / Frown\r\n                            const isRestricted = (category === \"restricted\");\r\n                            const smileCurve = new THREE.EllipseCurve(0, -0.05, 0.08, 0.05, 0, Math.PI, false, 0);\r\n                            const smilePoints = smileCurve.getPoints(10);\r\n                            const smileGeom = new THREE.BufferGeometry().setFromPoints(smilePoints);\r\n                            const smileLine = new THREE.Line(smileGeom, new THREE.LineBasicMaterial({ color: 0x000000, depthTest: false }));\r\n                            \r\n                            if (isRestricted) {\r\n                                // Frown\r\n                                smileLine.rotation.x = 0;\r\n                                smileLine.position.set(0, -0.05, 0.17); // Adjust position for frown\r\n                                \r\n                                // Eyebrows\r\n                                const eyebrowGeom = new THREE.BoxGeometry(0.06, 0.01, 0.01);\r\n                                const leftEyebrow = new THREE.Mesh(eyebrowGeom, eyeMat);\r\n                                leftEyebrow.position.set(-0.06, 0.07, 0.17);\r\n                                leftEyebrow.rotation.z = -0.3; // Angle inwards\r\n                                leftEyebrow.renderOrder = 999;\r\n                                headGroup.add(leftEyebrow);\r\n                                \r\n                                const rightEyebrow = new THREE.Mesh(eyebrowGeom, eyeMat);\r\n                                rightEyebrow.position.set(0.06, 0.07, 0.17);\r\n                                rightEyebrow.rotation.z = 0.3; // Angle inwards\r\n                                rightEyebrow.renderOrder = 999;\r\n                                headGroup.add(rightEyebrow);\r\n                            } else {\r\n                                // Smile\r\n                                smileLine.rotation.x = Math.PI;\r\n                                smileLine.position.z = 0.17;\r\n                            }\r\n                            \r\n                            smileLine.renderOrder = 999;\r\n                            headGroup.add(smileLine);\r\n\r\n                            npcGroup.add(headGroup);\r\n\r\n                            // Arms\r\n                            const armGeom = new THREE.BoxGeometry(0.12, 0.55, 0.12);\r\n                            \r\n                            const leftArmGroup = new THREE.Group();\r\n                            leftArmGroup.position.set(0.28, 1.15, 0); // NPC's left arm (our right)\r\n                            const leftArm = new THREE.Mesh(armGeom, clothesMat);\r\n                            leftArm.position.set(0, -0.15, 0);\r\n                            leftArm.renderOrder = 999;\r\n                            leftArmGroup.add(leftArm);\r\n                            \r\n                            const rightArmGroup = new THREE.Group();\r\n                            rightArmGroup.position.set(-0.28, 1.15, 0); // NPC's right arm (our left)\r\n                            const rightArm = new THREE.Mesh(armGeom, clothesMat);\r\n                            rightArm.position.set(0, -0.15, 0);\r\n                            rightArm.renderOrder = 999;\r\n                            rightArmGroup.add(rightArm);\r\n                            \r\n                            if (isRestricted) {\r\n                                // Cross arms forming X in front of chest\r\n                                leftArmGroup.rotation.order = 'ZXY';\r\n                                rightArmGroup.rotation.order = 'ZXY';\r\n                                \r\n                                leftArmGroup.rotation.z = -1.8; // Swing inwards and slightly up (under chin)\r\n                                leftArmGroup.rotation.x = -0.5; // Swing forward to clear chest\r\n                                \r\n                                rightArmGroup.rotation.z = 1.8; // Swing inwards and slightly up\r\n                                rightArmGroup.rotation.x = -0.6; // Swing more forward to overlap cleanly\r\n                            }\r\n                            \r\n                            npcGroup.add(leftArmGroup);\r\n                            npcGroup.add(rightArmGroup);\r\n\r\n                            // Legs\r\n                            const legGeom = new THREE.BoxGeometry(0.15, 0.7, 0.15);\r\n                            const leftLeg = new THREE.Mesh(legGeom, pantsMat);\r\n                            leftLeg.position.set(-0.1, 0.35, 0);\r\n                            leftLeg.renderOrder = 999;\r\n                            npcGroup.add(leftLeg);\r\n\r\n                            const rightLeg = new THREE.Mesh(legGeom, pantsMat);\r\n                            rightLeg.position.set(0.1, 0.35, 0);\r\n                            rightLeg.renderOrder = 999;\r\n                            npcGroup.add(rightLeg);\r\n\r\n                            // Invisible Hitbox\r\n                            const hitBoxGeom = new THREE.CylinderGeometry(0.5, 0.5, 1.8, 8);\r\n                            const hitBoxMat = new THREE.MeshBasicMaterial({ visible: false });\r\n                            const hitBox = new THREE.Mesh(hitBoxGeom, hitBoxMat);\r\n                            hitBox.position.y = 0.9;\r\n                            \r\n                            // Create HTML Label\r\n                            const labelDiv = document.createElement(\"div\");\r\n                            labelDiv.className = \"floating-label\";\r\n                            if (isRestricted) {\r\n                                labelDiv.classList.add(\"restricted\");\r\n                            }\r\n                            labelDiv.innerHTML = title;\r\n                            document.getElementById(\"floating-labels\").appendChild(labelDiv);\r\n\r\n                            hitBox.userData = { title, desc, category, isRestricted, parentGroup: npcGroup, rightArm: rightArmGroup, labelDiv: labelDiv };\r\n\r\n                            npcGroup.add(hitBox);\r\n                            scene.add(npcGroup);\r\n                            hotspots.push(hitBox);\r\n                        };\r\n\r\n                        // Unit 30: 360 Panorama Portal Badges\r\n                        const createPortalBadge = (sceneData) => {\r\n                            const x = sceneData.anchor_x;\r\n                            const y = sceneData.anchor_y != null ? sceneData.anchor_y : 1.6;\r\n                            const z = sceneData.anchor_z;\r\n                            const title = sceneData.title || \"360° Room\";\r\n\r\n                            const portalGroup = new THREE.Group();\r\n                            portalGroup.position.set(x, y, z);\r\n\r\n                            // Outer Glowing Cyan Ring\r\n                            const outerRingGeom = new THREE.RingGeometry(0.35, 0.42, 32);\r\n                            const outerRingMat = new THREE.MeshBasicMaterial({\r\n                                color: 0x00E5FF,\r\n                                side: THREE.DoubleSide,\r\n                                transparent: true,\r\n                                opacity: 0.9,\r\n                            });\r\n                            const outerRing = new THREE.Mesh(outerRingGeom, outerRingMat);\r\n                            portalGroup.add(outerRing);\r\n\r\n                            // Inner Pulsing Cyan Accent Ring\r\n                            const innerRingGeom = new THREE.RingGeometry(0.24, 0.28, 32);\r\n                            const innerRingMat = new THREE.MeshBasicMaterial({\r\n                                color: 0x96C0CE,\r\n                                side: THREE.DoubleSide,\r\n                                transparent: true,\r\n                                opacity: 0.8,\r\n                            });\r\n                            const innerRing = new THREE.Mesh(innerRingGeom, innerRingMat);\r\n                            portalGroup.add(innerRing);\r\n\r\n                            // Center Disc with 360° Icon Canvas Texture\r\n                            const pCanvas = document.createElement(\"canvas\");\r\n                            pCanvas.width = 128;\r\n                            pCanvas.height = 128;\r\n                            const pCtx = pCanvas.getContext(\"2d\");\r\n                            pCtx.fillStyle = \"rgba(7, 42, 48, 0.88)\";\r\n                            pCtx.beginPath();\r\n                            pCtx.arc(64, 64, 60, 0, Math.PI * 2);\r\n                            pCtx.fill();\r\n                            pCtx.lineWidth = 4;\r\n                            pCtx.strokeStyle = \"#00e5ff\";\r\n                            pCtx.stroke();\r\n                            pCtx.fillStyle = \"#ffffff\";\r\n                            pCtx.font = \"bold 40px sans-serif\";\r\n                            pCtx.textAlign = \"center\";\r\n                            pCtx.textBaseline = \"middle\";\r\n                            pCtx.fillText(\"360°\", 64, 64);\r\n\r\n                            const pTexture = new THREE.CanvasTexture(pCanvas);\r\n                            const centerGeom = new THREE.PlaneGeometry(0.44, 0.44);\r\n                            const centerMat = new THREE.MeshBasicMaterial({\r\n                                map: pTexture,\r\n                                transparent: true,\r\n                                side: THREE.DoubleSide,\r\n                            });\r\n                            const centerMesh = new THREE.Mesh(centerGeom, centerMat);\r\n                            portalGroup.add(centerMesh);\r\n\r\n                            // Clickable Invisible Hitbox\r\n                            const hitBoxGeom = new THREE.SphereGeometry(0.55, 12, 12);\r\n                            const hitBoxMat = new THREE.MeshBasicMaterial({ visible: false });\r\n                            const hitBox = new THREE.Mesh(hitBoxGeom, hitBoxMat);\r\n\r\n                            // HTML Floating Label\r\n                            const labelDiv = document.createElement(\"div\");\r\n                            labelDiv.className = \"floating-label portal-label\";\r\n                            labelDiv.innerHTML = `${title}<br><span style=\"font-size:10px;color:#00E5FF;font-weight:bold;\">TAP TO ENTER 360°</span>`;\r\n                            document.getElementById(\"floating-labels\").appendChild(labelDiv);\r\n\r\n\r\n                            hitBox.userData = {\r\n                                isPortal: true,\r\n                                sceneId: sceneData.id,\r\n                                sceneTitle: title,\r\n                                parentGroup: portalGroup,\r\n                                pulseMesh: innerRing,\r\n                                outerRing: outerRing,\r\n                                labelDiv: labelDiv,\r\n                            };\r\n\r\n                            portalGroup.add(hitBox);\r\n                            scene.add(portalGroup);\r\n                            hotspots.push(hitBox);\r\n                            portalBadges.push(hitBox);\r\n                        };\r\n\r\n                        // Load Dynamic Hotspots from the Database\r\n                        if (\r\n                            window.buildingHotspots &&\r\n                            window.buildingHotspots.length > 0\r\n                        ) {\r\n                            window.buildingHotspots.forEach((h) => {\r\n                                createHotspot(\r\n                                    h.x,\r\n                                    h.y,\r\n                                    h.z,\r\n                                    h.title,\r\n                                    h.desc || \"\",\r\n                                    0x00e5ff,\r\n                                    h.category\r\n                                );\r\n                            });\r\n                        }\r\n\r\n                        // Load 360 Panorama Portals from window.panoramaScenes\r\n                        if (\r\n                            window.panoramaScenes &&\r\n                            window.panoramaScenes.length > 0\r\n                        ) {\r\n                            window.panoramaScenes.forEach((sceneData) => {\r\n                                createPortalBadge(sceneData);\r\n                            });\r\n                        }\r\n\r\n\r\n                        document.getElementById(\"loading\").style.display =\r\n                            \"none\";\r\n                        window.ReactNativeWebView?.postMessage(\r\n                            JSON.stringify({ type: \"loaded\" }),\r\n                        );\r\n            }\r\n\r\n            function parseBase64Model(base64Data, fallbackUrl) {\r\n                ensureScene(controlMode);\r\n                document.getElementById(\"loading\").textContent = \"RENDERING INTERIOR...\";\r\n\r\n                try {\r\n                    const binaryString = window.atob(base64Data);\r\n                    const len = binaryString.length;\r\n                    const bytes = new Uint8Array(len);\r\n                    for (let i = 0; i < len; i++) {\r\n                        bytes[i] = binaryString.charCodeAt(i);\r\n                    }\r\n\r\n                    const loader = new GLTFLoader();\r\n                    const dracoLoader = new DRACOLoader();\r\n                    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');\r\n                    loader.setDRACOLoader(dracoLoader);\r\n\r\n                    loader.parse(\r\n                        bytes.buffer,\r\n                        \"\",\r\n                        (gltf) => {\r\n                            onInteriorModelLoaded(gltf);\r\n                        },\r\n                        (error) => {\r\n                            console.error(\"Cached interior model parse error:\", error);\r\n                            if (fallbackUrl) {\r\n                                loadModel(fallbackUrl);\r\n                            } else {\r\n                                const errMsg = (error && error.message) ? error.message : \"Failed to render cached interior model\";\r\n                                document.getElementById(\"loading\").textContent = \"LOAD ERROR\";\r\n                                window.ReactNativeWebView?.postMessage(\r\n                                    JSON.stringify({ type: \"error\", message: errMsg }),\r\n                                );\r\n                            }\r\n                        }\r\n                    );\r\n                } catch (e) {\r\n                    console.error(\"Base64 decode error:\", e);\r\n                    if (fallbackUrl) {\r\n                        loadModel(fallbackUrl);\r\n                    } else {\r\n                        document.getElementById(\"loading\").textContent = \"LOAD ERROR\";\r\n                        window.ReactNativeWebView?.postMessage(\r\n                            JSON.stringify({ type: \"error\", message: e.message }),\r\n                        );\r\n                    }\r\n                }\r\n            }\r\n\r\n            function loadModel(url) {\r\n                ensureScene(controlMode);\r\n                console.log(\"Starting to load interior model from:\", url);\r\n                const loader = new GLTFLoader();\r\n                \r\n                const dracoLoader = new DRACOLoader();\r\n                dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');\r\n                loader.setDRACOLoader(dracoLoader);\r\n                \r\n                loader.load(\r\n                    url,\r\n                    (gltf) => {\r\n                        onInteriorModelLoaded(gltf);\r\n                    },\r\n                    (progress) => {\r\n                        if (progress.total > 0) {\r\n                            const percent = Math.round(\r\n                                (progress.loaded / progress.total) * 100,\r\n                            );\r\n                            const mb = (progress.loaded / 1048576).toFixed(1);\r\n                            document.getElementById(\"loading\").textContent =\r\n                                `LOADING ${percent}% (${mb}MB)`;\r\n                            window.ReactNativeWebView?.postMessage(\r\n                                JSON.stringify({\r\n                                    type: \"progress\",\r\n                                    percent: percent,\r\n                                }),\r\n                            );\r\n                        }\r\n                    },\r\n                    (error) => {\r\n                        console.error(\"Model loading error:\", error);\r\n                        const errMsg = (error && error.message) ? error.message : \"Failed to load interior model. Please verify connection.\";\r\n                        document.getElementById(\"loading\").textContent =\r\n                            \"LOAD ERROR\";\r\n                        window.ReactNativeWebView?.postMessage(\r\n                            JSON.stringify({\r\n                                type: \"error\",\r\n                                message: errMsg,\r\n                            }),\r\n                        );\r\n                    },\r\n                );\r\n            }\r\n\r\n            // ✨ Animation Loop ✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨✨\r\n            const velocity = new THREE.Vector3();\r\n            let velocityY = 0;\r\n            const direction = new THREE.Vector3();\r\n            const tempVector = new THREE.Vector3();\r\n\r\n            function animate() {\r\n                animFrameId = requestAnimationFrame(animate);\r\n\r\n                // Auto-detect nearby NPCs and update labels\r\n                let minDist = 3.5;\r\n                const time = performance.now() * 0.003;\r\n\r\n                hotspots.forEach((h) => {\r\n                    if (h.userData.isPortal) return;\r\n                    const npcGroup = h.userData.parentGroup;\r\n                    const rightArm = h.userData.rightArm;\r\n                    const labelDiv = h.userData.labelDiv;\r\n                    \r\n                    npcGroup.getWorldPosition(tempVector);\r\n                    const dist = tempVector.distanceTo(camera.position);\r\n                    \r\n                    // Face camera\r\n                    const targetPos = camera.position.clone();\r\n                    targetPos.y = npcGroup.position.y;\r\n                    npcGroup.lookAt(targetPos);\r\n                    \r\n                    // Wave and expand bubble if close\r\n                    if (dist < minDist) {\r\n                        if (!h.userData.isRestricted) {\r\n                            rightArm.rotation.z = -2.0 + Math.sin(time * 1.5) * 0.5;\r\n                            rightArm.rotation.x = Math.sin(time) * 0.2;\r\n                        }\r\n                        labelDiv.innerHTML = h.userData.title + (h.userData.desc ? \"<br><span style='font-size:12px;font-weight:normal;'>\" + h.userData.desc + \"</span>\" : \"\");\r\n                    } else {\r\n                        if (!h.userData.isRestricted) {\r\n                            rightArm.rotation.z = 0;\r\n                            rightArm.rotation.x = 0;\r\n                        }\r\n                        labelDiv.innerHTML = h.userData.title;\r\n                    }\r\n\r\n                    // Update label position\r\n                    tempVector.y += 1.8; // Above head\r\n                    tempVector.project(camera);\r\n                    \r\n                    if (tempVector.z > 1) {\r\n                        labelDiv.style.opacity = \"0\";\r\n                    } else {\r\n                        labelDiv.style.opacity = \"1\";\r\n                        const x = (tempVector.x *  0.5 + 0.5) * window.innerWidth;\r\n                        const y = (tempVector.y * -0.5 + 0.5) * window.innerHeight;\r\n                        labelDiv.style.left = `${x}px`;\r\n                        labelDiv.style.top = `${y}px`;\r\n                    }\r\n                });\r\n\r\n                // Animate 360 Portal Badges (Unit 30)\r\n                portalBadges.forEach((p) => {\r\n                    const pGroup = p.userData.parentGroup;\r\n                    const labelDiv = p.userData.labelDiv;\r\n                    // Always face the camera\r\n                    pGroup.quaternion.copy(camera.quaternion);\r\n\r\n                    // Pulse animation\r\n                    if (p.userData.pulseMesh) {\r\n                        const s = 1 + Math.sin(time * 3) * 0.08;\r\n                        p.userData.pulseMesh.scale.set(s, s, s);\r\n                    }\r\n\r\n                    // Position floating HTML label above portal\r\n                    pGroup.getWorldPosition(tempVector);\r\n                    const dist = tempVector.distanceTo(camera.position);\r\n                    tempVector.y += 0.55;\r\n                    tempVector.project(camera);\r\n\r\n                    if (tempVector.z > 1 || dist > 25) {\r\n                        labelDiv.style.opacity = \"0\";\r\n                    } else {\r\n                        const opacity = dist < 8 ? \"1\" : Math.max(0, 1 - (dist - 8) / 8).toFixed(2);\r\n                        labelDiv.style.opacity = opacity;\r\n                        const lx = (tempVector.x * 0.5 + 0.5) * window.innerWidth;\r\n                        const ly = (tempVector.y * -0.5 + 0.5) * window.innerHeight;\r\n                        labelDiv.style.left = `${lx}px`;\r\n                        labelDiv.style.top = `${ly}px`;\r\n                    }\r\n                });\r\n\r\n                // Broadcast camera position at ~10 FPS for mobile proximity HUD (Unit 30)\r\n                const now = performance.now();\r\n                if (now - lastCamBroadcastTime > 100) {\r\n                    lastCamBroadcastTime = now;\r\n                    window.ReactNativeWebView?.postMessage(\r\n                        JSON.stringify({\r\n                            type: \"camera_position\",\r\n                            x: Number(camera.position.x.toFixed(2)),\r\n                            y: Number(camera.position.y.toFixed(2)),\r\n                            z: Number(camera.position.z.toFixed(2)),\r\n                        })\r\n                    );\r\n                }\r\n\r\n\r\n                if (model) {\r\n                    // Apply gyroscope camera rotation FIRST (before movement processing)\r\n                    if (controlMode === \"gyroscope\") {\r\n                        applyGyroToCamera();\r\n                    }\r\n\r\n                    // In joystick mode: save the look-target offset so movement doesn't break the angle\r\n                    const targetOffset =\r\n                        controlMode !== \"gyroscope\"\r\n                            ? controls.target.clone().sub(camera.position)\r\n                            : null;\r\n\r\n                    // Animate NPC hotspots\r\n                    // Removed old spinning loop\r\n\r\n                    // Handle Teleport Animation OR Gravity\r\n                    if (teleportTarget) {\r\n                        teleportProgress += TELEPORT_SPEED;\r\n                        if (teleportProgress >= 1) {\r\n                            camera.position.copy(teleportTarget);\r\n                            teleportTarget = null;\r\n                            if (teleportMarker) teleportMarker.visible = false;\r\n                        } else {\r\n                            // Smooth easing (ease-out cubic)\r\n                            const t = teleportProgress;\r\n                            const ease = 1 - Math.pow(1 - t, 3);\r\n                            \r\n                            // To prevent weird camera jitter while teleporting, we interpolate the position\r\n                            // directly rather than applying gravity or movement.\r\n                            camera.position.lerpVectors(teleportStartPos, teleportTarget, ease);\r\n                            \r\n                            // Fade out the marker\r\n                            if (teleportMarker) {\r\n                                teleportMarker.material.opacity = 0.8 * (1 - ease);\r\n                            }\r\n                        }\r\n                    } else {\r\n                        // Downward Raycast for Floor Height (Stairs / Gravity)\r\n                        // Runs when moving OR airborne — gravity must apply even when joystick is released mid-air\r\n                        const isActiveOrAirborne = (moveForward !== 0 || moveRight !== 0 || velocityY !== 0);\r\n                        if (!ghostMode && isActiveOrAirborne) {\r\n                            const origin = camera.position.clone();\r\n                            origin.y += 0.8; // Cast from eye level downwards\r\n                            floorRaycaster.set(origin, downVector);\r\n                            const floorHits = floorRaycaster.intersectObject(model, true);\r\n\r\n                            const validHit = floorHits.find(hit => hit.point.y < camera.position.y + 0.5);\r\n\r\n                            if (validHit) {\r\n                                const floorY = validHit.point.y;\r\n                                const targetY = floorY + 1.6;\r\n                                const diff = targetY - camera.position.y;\r\n                                \r\n                                if (diff > 0 && diff <= 0.6) {\r\n                                    // Step Up: Only snap up if the obstacle is a real stair (< 0.6m)\r\n                                    camera.position.y += diff * 0.25;\r\n                                    velocityY = 0; // Grounded\r\n                                } else if (diff < 0 && diff >= -0.6) {\r\n                                    // Step Down: Small drop like walking down stairs\r\n                                    camera.position.y += diff * 0.25;\r\n                                    velocityY = 0; // Grounded\r\n                                } else if (diff < -0.6) {\r\n                                    // Free Fall: The floor is far below us\r\n                                    velocityY -= 0.008; // Real Gravity acceleration\r\n                                    camera.position.y += Math.max(diff, velocityY); // Fall but do not clip through floor\r\n                                } else {\r\n                                    // Hitting a Wall/Ladder: obstacle is > 0.6m high (too tall to step up)\r\n                                    if (camera.position.y > targetY + 0.1) {\r\n                                        velocityY -= 0.008;\r\n                                        camera.position.y += velocityY;\r\n                                    } else {\r\n                                        velocityY = 0; // Grounded against base of wall\r\n                                    }\r\n                                }\r\n                            } else {\r\n                                // Laser missed interior geometry: stay grounded on the campus base plane\r\n                                const baseGroundY = box.min.y + 1.6;\r\n                                if (camera.position.y < box.min.y - 1.0) {\r\n                                    // Player fell into the void -> Auto-respawn to safe location!\r\n                                    if (window.safeSpawnPos) {\r\n                                        camera.position.copy(window.safeSpawnPos);\r\n                                        velocityY = 0;\r\n                                    }\r\n                                } else if (camera.position.y > baseGroundY) {\r\n                                    velocityY -= 0.008;\r\n                                    camera.position.y = Math.max(baseGroundY, camera.position.y + velocityY);\r\n                                    if (camera.position.y === baseGroundY) velocityY = 0;\r\n                                } else {\r\n                                    camera.position.y = baseGroundY;\r\n                                    velocityY = 0;\r\n                                }\r\n                            }\r\n                        }\r\n                    }\r\n\r\n                    // Movement (joystick input — works in both modes)\r\n                    if (moveForward !== 0 || moveRight !== 0) {\r\n                        const forwardVector = new THREE.Vector3(\r\n                            0,\r\n                            0,\r\n                            -1,\r\n                        ).applyQuaternion(camera.quaternion);\r\n                        forwardVector.y = 0;\r\n                        forwardVector.normalize();\r\n\r\n                        const rightVector = new THREE.Vector3(\r\n                            1,\r\n                            0,\r\n                            0,\r\n                        ).applyQuaternion(camera.quaternion);\r\n                        rightVector.y = 0;\r\n                        rightVector.normalize();\r\n\r\n                        let transX =\r\n                            forwardVector.x * moveForward +\r\n                            rightVector.x * moveRight;\r\n                        let transZ =\r\n                            forwardVector.z * moveForward +\r\n                            rightVector.z * moveRight;\r\n\r\n                        // Horizontal wall collision raycasts (only when actively moving)\r\n                        const moveVector = new THREE.Vector3(transX, 0, transZ);\r\n                        if (moveVector.lengthSq() > 0.0001) {\r\n                            const moveDir = moveVector.clone().normalize();\r\n\r\n                            const isSolid = (hit) => {\r\n                                let obj = hit.object;\r\n                                while (obj) {\r\n                                    if (obj.userData.isOpen) return false;\r\n                                    obj = obj.parent;\r\n                                }\r\n                                return true;\r\n                            };\r\n\r\n                            // Eye-level check (bounded to 1.0m)\r\n                            wallRaycaster.set(camera.position, moveDir);\r\n                            const eyeHits = wallRaycaster\r\n                                .intersectObject(model, true)\r\n                                .filter(isSolid);\r\n\r\n                            // Waist-level check (bounded to 1.0m)\r\n                            const waistOrigin = camera.position.clone();\r\n                            waistOrigin.y -= 0.8;\r\n                            wallRaycaster.set(waistOrigin, moveDir);\r\n                            const waistHits = wallRaycaster\r\n                                .intersectObject(model, true)\r\n                                .filter(isSolid);\r\n\r\n                            const eyeDist =\r\n                                eyeHits.length > 0\r\n                                    ? eyeHits[0].distance\r\n                                    : Infinity;\r\n                            const waistDist =\r\n                                waistHits.length > 0\r\n                                    ? waistHits[0].distance\r\n                                    : Infinity;\r\n\r\n                            if (\r\n                                !ghostMode &&\r\n                                Math.min(eyeDist, waistDist) < COLLISION_DISTANCE\r\n                            ) {\r\n                                // ── Wall Sliding (axis-split collision) ──────────────────\r\n                                // Instead of a hard full-stop, test each axis independently.\r\n                                // This lets the player slide along walls when moving at an angle.\r\n                                let canX = true;\r\n                                let canZ = true;\r\n\r\n                                // Test X-only movement\r\n                                if (Math.abs(transX) > 0.0001) {\r\n                                    const xDir = new THREE.Vector3(Math.sign(transX), 0, 0);\r\n                                    wallRaycaster.set(camera.position, xDir);\r\n                                    const xEye = wallRaycaster.intersectObject(model, true).filter(isSolid);\r\n                                    wallRaycaster.set(waistOrigin, xDir);\r\n                                    const xWaist = wallRaycaster.intersectObject(model, true).filter(isSolid);\r\n                                    const xDist = Math.min(\r\n                                        xEye.length > 0 ? xEye[0].distance : Infinity,\r\n                                        xWaist.length > 0 ? xWaist[0].distance : Infinity\r\n                                    );\r\n                                    if (xDist < COLLISION_DISTANCE) canX = false;\r\n                                }\r\n\r\n                                // Test Z-only movement\r\n                                if (Math.abs(transZ) > 0.0001) {\r\n                                    const zDir = new THREE.Vector3(0, 0, Math.sign(transZ));\r\n                                    wallRaycaster.set(camera.position, zDir);\r\n                                    const zEye = wallRaycaster.intersectObject(model, true).filter(isSolid);\r\n                                    wallRaycaster.set(waistOrigin, zDir);\r\n                                    const zWaist = wallRaycaster.intersectObject(model, true).filter(isSolid);\r\n                                    const zDist = Math.min(\r\n                                        zEye.length > 0 ? zEye[0].distance : Infinity,\r\n                                        zWaist.length > 0 ? zWaist[0].distance : Infinity\r\n                                    );\r\n                                    if (zDist < COLLISION_DISTANCE) canZ = false;\r\n                                }\r\n\r\n                                if (!canX) transX = 0;\r\n                                if (!canZ) transZ = 0;\r\n                            }\r\n                        }\r\n\r\n                        camera.position.x += transX;\r\n                        camera.position.z += transZ;\r\n\r\n                        if (worldBounds) {\r\n                            camera.position.clamp(\r\n                                worldBounds.min,\r\n                                worldBounds.max,\r\n                            );\r\n                        }\r\n                    }\r\n\r\n                    // In joystick mode: reapply look angle after position move\r\n                    if (controlMode !== \"gyroscope\" && targetOffset) {\r\n                        controls.target.copy(camera.position).add(targetOffset);\r\n                    }\r\n                }\r\n\r\n                // Only call OrbitControls.update() in joystick mode —\r\n                // in gyro mode it would overwrite the quaternion we just set\r\n                if (controlMode !== \"gyroscope\") {\r\n                    controls.update();\r\n                }\r\n                renderer.render(scene, camera);\r\n            }\r\n\r\n            function onWindowResize() {\r\n                camera.aspect = window.innerWidth / window.innerHeight;\r\n                camera.updateProjectionMatrix();\r\n                renderer.setSize(window.innerWidth, window.innerHeight);\r\n            }\r\n\r\n            // ── Dispose / Cleanup ──────────────────────────────────────────\r\n            function dispose() {\r\n                if (animFrameId) {\r\n                    cancelAnimationFrame(animFrameId);\r\n                    animFrameId = null;\r\n                }\r\n                window.removeEventListener(\"resize\", onWindowResize);\r\n                // Gyro data came from RN postMessage — no DOM listener to remove\r\n                gyroEnabled = false;\r\n                if (model && scene) {\r\n                    scene.remove(model);\r\n                    model.traverse((child) => {\r\n                        if (child.geometry) child.geometry.dispose();\r\n                        if (child.material) {\r\n                            if (Array.isArray(child.material)) {\r\n                                child.material.forEach((m) => m.dispose());\r\n                            } else {\r\n                                child.material.dispose();\r\n                            }\r\n                        }\r\n                    });\r\n                }\r\n                if (portalBadges && portalBadges.length > 0) {\r\n                    portalBadges.forEach((p) => {\r\n                        if (p.userData && p.userData.labelDiv && p.userData.labelDiv.parentNode) {\r\n                            p.userData.labelDiv.parentNode.removeChild(p.userData.labelDiv);\r\n                        }\r\n                        if (scene) scene.remove(p);\r\n                    });\r\n                    portalBadges = [];\r\n                }\r\n                if (renderer) renderer.dispose();\r\n                if (controls) controls.dispose();\r\n            }\r\n\r\n            function refreshPortalBadges() {\r\n                if (portalBadges && portalBadges.length > 0) {\r\n                    portalBadges.forEach((p) => {\r\n                        if (p.userData && p.userData.labelDiv && p.userData.labelDiv.parentNode) {\r\n                            p.userData.labelDiv.parentNode.removeChild(p.userData.labelDiv);\r\n                        }\r\n                        if (scene) scene.remove(p);\r\n                    });\r\n                    portalBadges = [];\r\n                }\r\n                if (window.panoramaScenes && window.panoramaScenes.length > 0) {\r\n                    window.panoramaScenes.forEach((sceneData) => {\r\n                        createPortalBadge(sceneData);\r\n                    });\r\n                }\r\n            }\r\n\r\n\r\n            function resetToEntrance() {\r\n                if (!window.safeSpawnPos || !camera || !controls) return;\r\n                camera.position.copy(window.safeSpawnPos);\r\n                velocityY = 0;\r\n                moveForward = 0;\r\n                moveRight = 0;\r\n\r\n                // Run 8-direction raycast to find the most open facing direction\r\n                const facingRaycaster = new THREE.Raycaster();\r\n                facingRaycaster.far = 4.0;\r\n                const spawnEye = camera.position.clone();\r\n                const DIRECTIONS_8 = [0, 45, 90, 135, 180, 225, 270, 315];\r\n                let bestAngle = 0;\r\n                let bestDist = -1;\r\n                DIRECTIONS_8.forEach((deg) => {\r\n                    const rad = THREE.MathUtils.degToRad(deg);\r\n                    const dir = new THREE.Vector3(Math.sin(rad), 0, Math.cos(rad));\r\n                    facingRaycaster.set(spawnEye, dir);\r\n                    const hits = facingRaycaster.intersectObject(model, true);\r\n                    const dist = hits.length > 0 ? hits[0].distance : facingRaycaster.far;\r\n                    if (dist > bestDist) {\r\n                        bestDist = dist;\r\n                        bestAngle = rad;\r\n                    }\r\n                });\r\n                const facingTarget = new THREE.Vector3(\r\n                    camera.position.x + Math.sin(bestAngle),\r\n                    camera.position.y,\r\n                    camera.position.z + Math.cos(bestAngle),\r\n                );\r\n                controls.target.copy(facingTarget);\r\n                controls.update();\r\n\r\n                // Smooth fade-in overlay transition\r\n                let fadeEl = document.getElementById(\"spawn-fade\");\r\n                if (!fadeEl) {\r\n                    fadeEl = document.createElement(\"div\");\r\n                    fadeEl.id = \"spawn-fade\";\r\n                    document.body.appendChild(fadeEl);\r\n                }\r\n                fadeEl.classList.remove(\"faded\");\r\n                requestAnimationFrame(() => {\r\n                    requestAnimationFrame(() => {\r\n                        fadeEl.classList.add(\"faded\");\r\n                        fadeEl.addEventListener(\r\n                            \"transitionend\",\r\n                            () => fadeEl.remove(),\r\n                            { once: true },\r\n                        );\r\n                    });\r\n                });\r\n            }\r\n\r\n            // ── Message Handlers (window + document for Android WebView) ──\r\n            function handleIncomingMessage(data) {\r\n                if (data.type === \"model_chunk_start\") {\r\n                    if (data.controlMode) controlMode = data.controlMode;\r\n                    ensureScene(data.controlMode || \"joystick\");\r\n                    window.buildingHotspots = data.hotspots || window.buildingHotspots || [];\r\n                    window.panoramaScenes = (data.panoramaScenes || window.panoramaScenes || []).filter(\r\n                        (s) => s.anchor_x != null && s.anchor_z != null\r\n                    );\r\n                    chunkCollector = {\r\n                        totalChunks: data.totalChunks,\r\n                        chunks: new Array(data.totalChunks),\r\n                        receivedCount: 0,\r\n                        fallbackUrl: data.fallbackUrl,\r\n                    };\r\n                    document.getElementById(\"loading\").textContent = \"LOADING FROM STORAGE...\";\r\n                } else if (data.type === \"model_chunk\") {\r\n                    if (chunkCollector.chunks && !chunkCollector.chunks[data.index]) {\r\n                        chunkCollector.chunks[data.index] = data.chunk;\r\n                        chunkCollector.receivedCount++;\r\n                        const pct = Math.round((chunkCollector.receivedCount / chunkCollector.totalChunks) * 100);\r\n                        document.getElementById(\"loading\").textContent = `LOADING FROM STORAGE... ${pct}%`;\r\n                        window.ReactNativeWebView?.postMessage(\r\n                            JSON.stringify({ type: \"progress\", percent: pct }),\r\n                        );\r\n                        if (chunkCollector.receivedCount === chunkCollector.totalChunks) {\r\n                            const fullBase64 = chunkCollector.chunks.join(\"\");\r\n                            chunkCollector.chunks = null; // free memory immediately\r\n                            parseBase64Model(fullBase64, chunkCollector.fallbackUrl);\r\n                        }\r\n                    }\r\n                } else if (data.type === \"init\") {\r\n                    window.buildingHotspots = data.hotspots || [];\r\n                    // Unit 30: Store panorama scene anchors for portal badge spawning\r\n                    window.panoramaScenes = (data.panoramaScenes || []).filter(\r\n                        (s) => s.anchor_x != null && s.anchor_z != null\r\n                    );\r\n                    init(data.modelUrl, data.controlMode || \"joystick\");\r\n                } else if (data.type === \"update_panorama_scenes\") {\r\n                    // Update portal badges dynamically without tearing down Three.js model\r\n                    window.panoramaScenes = (data.panoramaScenes || []).filter(\r\n                        (s) => s.anchor_x != null && s.anchor_z != null\r\n                    );\r\n                    if (scene && model) {\r\n                        refreshPortalBadges();\r\n                    }\r\n                } else if (data.type === \"gyro_data\") {\r\n                    // Native sensor data bridged from React Native expo-sensors DeviceMotion\r\n                    onGyroData(\r\n                        data.alpha,\r\n                        data.beta,\r\n                        data.gamma,\r\n                        data.orientAngle,\r\n                    );\r\n                } else if (data.type === \"reset_entrance\") {\r\n                    resetToEntrance();\r\n                } else if (data.type === \"set_control_mode\") {\r\n                    controlMode = data.mode || \"joystick\";\r\n                    if (data.mode === \"gyroscope\") {\r\n                        startGyroscope();\r\n                    } else {\r\n                        gyroEnabled = false;\r\n                        const gyroInd = document.getElementById(\"gyro-indicator\");\r\n                        if (gyroInd) gyroInd.style.display = \"none\";\r\n                        const camZone = document.getElementById(\"camera-zone\");\r\n                        if (camZone) camZone.style.pointerEvents = \"auto\";\r\n                        const inst = document.getElementById(\"instructions\");\r\n                        if (inst) inst.innerHTML = \"Drag right side to look<br />Use joystick to move\";\r\n                        if (controls) controls.enabled = true;\r\n                    }\r\n                } else if (data.type === \"set_speed\") {\r\n                    MOVE_SPEED = Number(data.speed) || 0.18;\r\n                } else if (data.type === \"set_sensitivity\") {\r\n                    if (controls) controls.rotateSpeed = Number(data.sensitivity) || 0.85;\r\n                } else if (data.type === \"set_labels_visible\") {\r\n                    const labelsEl = document.getElementById(\"floating-labels\");\r\n                    if (labelsEl) labelsEl.style.display = data.visible ? \"block\" : \"none\";\r\n                } else if (data.type === \"set_ghost_mode\") {\r\n                    ghostMode = Boolean(data.enabled);\r\n                } else if (data.type === \"dispose\") {\r\n                    dispose();\r\n                }\r\n            }\r\n\r\n            window.addEventListener(\"message\", (event) => {\r\n                try {\r\n                    const data =\r\n                        typeof event.data === \"string\"\r\n                            ? JSON.parse(event.data)\r\n                            : event.data;\r\n                    handleIncomingMessage(data);\r\n                } catch (e) {\r\n                    console.error(\"Message parse error:\", e);\r\n                }\r\n            });\r\n\r\n            document.addEventListener(\"message\", (event) => {\r\n                try {\r\n                    const data =\r\n                        typeof event.data === \"string\"\r\n                            ? JSON.parse(event.data)\r\n                            : event.data;\r\n                    handleIncomingMessage(data);\r\n                } catch (e) {\r\n                    console.error(\"Message parse error:\", e);\r\n                }\r\n            });\r\n        </script>\r\n    </body>\r\n</html>\r\n";
